              when md5(prompt) = '77b730943fef05a6d9c7e96d56f86e0c' and md5(coalesce(explanation, '')) = '6fa3f0c65626a7f39b3cb2beca4fc3f4' and md5(options::text) = md5('["Nothing but the converted values, since the source unit is dropped for good once the curve is in metres", "The source unit and the factor used, stored on the curve so the conversion stays auditable", "A second index curve holding the original feet depths beside the new metric frame", "An unconverted flag, so the import screen asks a human to confirm the unit"]'::jsonb::text) and answer_index = 1 then 'new'
