           answer_index = 2, explanation = 'The capstone earns the Associate certification in Well Data Manager. That certificate is the prerequisite root of the whole geoscience path, so petrophysics, correlation, seismic, mapping and volumetrics all sit behind it.'
     where app_slug = 'welldata' and tier = 'beginner' and scope = 'module' and module_key is not distinct from 'm06-the-qc-workflow' and ord = 13 and active;
